=== FILE: sync_fifo.v ===
// sync_fifo: parameterizable synchronous FIFO.
// Serves requirement req-d57ae7630b. Ports and behaviour from interface_spec.md;
// structure from microarchitecture.md (explicit count register, LAST-compare
// pointer wrap, first-word fall-through read, unreset storage).
`default_nettype none

module sync_fifo #(
    parameter integer DEPTH = 8,   // entries, 2 or more, any value
    parameter integer WIDTH = 8    // bits per entry, 1 or more
) (
    input  wire                       clk,
    input  wire                       rst_n,    // synchronous, active low
    input  wire                       wr_en,
    input  wire [WIDTH-1:0]           wr_data,
    output wire                       full,
    input  wire                       rd_en,
    output wire [WIDTH-1:0]           rd_data,
    output wire                       empty,
    output wire [$clog2(DEPTH+1)-1:0] count
);

    localparam integer PW   = $clog2(DEPTH);       // pointer width
    localparam integer CW   = $clog2(DEPTH + 1);   // count width, holds DEPTH
    localparam integer LAST = DEPTH - 1;           // last slot index
    localparam [CW-1:0] CNT_ONE = {{(CW-1){1'b0}}, 1'b1};

    // Storage: datapath, not reset.
    reg  [WIDTH-1:0] mem [0:DEPTH-1];

    // State registers and their next values.
    reg  [PW-1:0]    wr_ptr_q;
    reg  [PW-1:0]    rd_ptr_q;
    reg  [CW-1:0]    count_q;
    reg  [PW-1:0]    wr_ptr_d;
    reg  [PW-1:0]    rd_ptr_d;
    reg  [CW-1:0]    count_d;

    wire [PW-1:0]    ptr_one;
    wire [31:0]      wr_ptr_ext;
    wire [31:0]      rd_ptr_ext;
    wire [31:0]      count_ext;
    wire             wr_wrap;
    wire             rd_wrap;
    wire             wr_acc;
    wire             rd_acc;

    // Sized constant one for pointer increments (PW may be 1).
    generate
        if (PW == 1) begin : g_ptr_one_narrow
            assign ptr_one = 1'b1;
        end else begin : g_ptr_one_wide
            assign ptr_one = {{(PW-1){1'b0}}, 1'b1};
        end
    endgenerate

    // Width-matched compares against integer parameters.
    assign wr_ptr_ext = {{(32-PW){1'b0}}, wr_ptr_q};
    assign rd_ptr_ext = {{(32-PW){1'b0}}, rd_ptr_q};
    assign count_ext  = {{(32-CW){1'b0}}, count_q};

    assign wr_wrap = (wr_ptr_ext == LAST);
    assign rd_wrap = (rd_ptr_ext == LAST);

    // Flags are compares on the count register only.
    assign full  = (count_ext == DEPTH);
    assign empty = (count_q == {CW{1'b0}});

    // Accepted requests: the flags gate the requests (overflow/underflow policy).
    assign wr_acc = wr_en & ~full;
    assign rd_acc = rd_en & ~empty;

    // Next-state logic.
    always @* begin
        wr_ptr_d = wr_ptr_q;
        if (wr_acc) begin
            if (wr_wrap) begin
                wr_ptr_d = {PW{1'b0}};
            end else begin
                wr_ptr_d = wr_ptr_q + ptr_one;
            end
        end

        rd_ptr_d = rd_ptr_q;
        if (rd_acc) begin
            if (rd_wrap) begin
                rd_ptr_d = {PW{1'b0}};
            end else begin
                rd_ptr_d = rd_ptr_q + ptr_one;
            end
        end

        count_d = count_q;
        if (wr_acc && !rd_acc) begin
            count_d = count_q + CNT_ONE;
        end else if (rd_acc && !wr_acc) begin
            count_d = count_q - CNT_ONE;
        end
    end

    // State registers: synchronous active-low reset, then the update.
    always @(posedge clk) begin
        if (!rst_n) begin
            wr_ptr_q <= {PW{1'b0}};
            rd_ptr_q <= {PW{1'b0}};
            count_q  <= {CW{1'b0}};
        end else begin
            wr_ptr_q <= wr_ptr_d;
            rd_ptr_q <= rd_ptr_d;
            count_q  <= count_d;
        end
    end

    // Storage write, only outside reset.
    always @(posedge clk) begin
        if (rst_n && wr_acc) begin
            mem[wr_ptr_q] <= wr_data;
        end
    end

    // First-word fall-through read of the oldest slot.
    assign rd_data = mem[rd_ptr_q];
    assign count   = count_q;

endmodule

`default_nettype wire
=== END FILE ===
