// sync_fifo_tb: self-checking testbench for sync_fifo (requirement req-d57ae7630b).
// Two FIFOs on one stimulus: DEPTH 8 x WIDTH 8 and DEPTH 5 x WIDTH 12, each
// checked every cycle against a reference queue, with corner-case coverage.
`timescale 1ns/1ps

module sync_fifo_tb;

    reg            clk;
    reg            rst_n;
    reg            wr_en;
    reg            rd_en;
    reg  [11:0]    wr_data;
    reg  [31:0]    rnd;
    reg  [31:0]    sel;
    reg  [31:0]    passed;
    reg  [31:0]    failed;
    reg  [8*64-1:0] nonce;
    integer        k;

    wire [31:0]    pass_a;
    wire [31:0]    fail_a;
    wire [31:0]    pass_b;
    wire [31:0]    fail_b;
    wire [9:0]     cov_a;
    wire [9:0]     cov_b;

    sync_fifo_tb_lane #(.DEPTH(8), .WIDTH(8)) u_lane_a (
        .clk     (clk),
        .rst_n   (rst_n),
        .wr_en   (wr_en),
        .wr_data (wr_data[7:0]),
        .rd_en   (rd_en),
        .passed  (pass_a),
        .failed  (fail_a),
        .cov     (cov_a)
    );

    sync_fifo_tb_lane #(.DEPTH(5), .WIDTH(12)) u_lane_b (
        .clk     (clk),
        .rst_n   (rst_n),
        .wr_en   (wr_en),
        .wr_data (wr_data),
        .rd_en   (rd_en),
        .passed  (pass_b),
        .failed  (fail_b),
        .cov     (cov_b)
    );

    initial clk = 1'b0;
    always #5 clk = ~clk;

    // Apply one cycle of stimulus, then let one rising edge pass.
    task drive_cycle;
        input w;
        input r;
        input rs;
        begin
            wr_en = w;
            rd_en = r;
            rst_n = rs;
            rnd = $random;
            wr_data = rnd[11:0];
            @(posedge clk);
            #1;
        end
    endtask

    initial begin
        passed = 32'd0;
        failed = 32'd0;
        nonce  = {64{8'h00}};

        // Reset.
        for (k = 0; k < 3; k = k + 1) drive_cycle(1'b0, 1'b0, 1'b0);
        // Read while empty.
        for (k = 0; k < 2; k = k + 1) drive_cycle(1'b0, 1'b1, 1'b1);
        // Write and read together when empty, then read the entry back.
        drive_cycle(1'b1, 1'b1, 1'b1);
        drive_cycle(1'b0, 1'b1, 1'b1);
        // Fill to full, with writes while full.
        for (k = 0; k < 10; k = k + 1) drive_cycle(1'b1, 1'b0, 1'b1);
        // Write and read together when full, then in between.
        for (k = 0; k < 2; k = k + 1) drive_cycle(1'b1, 1'b1, 1'b1);
        // Drain to empty, with reads while empty.
        for (k = 0; k < 10; k = k + 1) drive_cycle(1'b0, 1'b1, 1'b1);

        // Random traffic, write-biased.
        for (k = 0; k < 200; k = k + 1) begin
            sel = $random;
            drive_cycle(sel[1:0] != 2'b00, sel[3:2] == 2'b00, 1'b1);
        end
        // Random traffic, read-biased.
        for (k = 0; k < 200; k = k + 1) begin
            sel = $random;
            drive_cycle(sel[1:0] == 2'b00, sel[3:2] != 2'b00, 1'b1);
        end
        // Random traffic, balanced.
        for (k = 0; k < 300; k = k + 1) begin
            sel = $random;
            drive_cycle(sel[0], sel[1], 1'b1);
        end

        // Reset during traffic, with requests held high during reset.
        for (k = 0; k < 3; k = k + 1) drive_cycle(1'b1, 1'b0, 1'b1);
        for (k = 0; k < 2; k = k + 1) drive_cycle(1'b1, 1'b1, 1'b0);
        for (k = 0; k < 300; k = k + 1) begin
            sel = $random;
            drive_cycle(sel[0], sel[1], 1'b1);
        end

        // Idle, then collect the verdict.
        for (k = 0; k < 2; k = k + 1) drive_cycle(1'b0, 1'b0, 1'b1);
        @(negedge clk);
        #1;

        passed = pass_a + pass_b;
        failed = fail_a + fail_b;

        if (cov_a != 10'h3FF) begin
            $error("sync_fifo_tb: DEPTH 8 lane missed coverage, bitmap %b", cov_a);
            failed = failed + 32'd1;
        end else begin
            passed = passed + 32'd1;
        end
        if (cov_b != 10'h3FF) begin
            $error("sync_fifo_tb: DEPTH 5 lane missed coverage, bitmap %b", cov_b);
            failed = failed + 32'd1;
        end else begin
            passed = passed + 32'd1;
        end

        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) begin
            nonce = {64{8'h00}};
        end
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule

// One DUT plus its reference queue, per-cycle checks and coverage bits.
// Coverage bits: 0 fill to full, 1 write while full, 2 drain to empty,
// 3 read while empty, 4 write+read when empty, 5 write+read when full,
// 6 write+read in between, 7 write pointer wrap, 8 read pointer wrap,
// 9 reset during traffic.
module sync_fifo_tb_lane #(
    parameter integer DEPTH = 8,
    parameter integer WIDTH = 8
) (
    input  wire             clk,
    input  wire             rst_n,
    input  wire             wr_en,
    input  wire [WIDTH-1:0] wr_data,
    input  wire             rd_en,
    output reg  [31:0]      passed,
    output reg  [31:0]      failed,
    output wire [9:0]       cov
);

    localparam integer CW = $clog2(DEPTH + 1);

    wire             full;
    wire             empty;
    wire [WIDTH-1:0] rd_data;
    wire [CW-1:0]    count;

    sync_fifo #(.DEPTH(DEPTH), .WIDTH(WIDTH)) u_dut (
        .clk     (clk),
        .rst_n   (rst_n),
        .wr_en   (wr_en),
        .wr_data (wr_data),
        .full    (full),
        .rd_en   (rd_en),
        .rd_data (rd_data),
        .empty   (empty),
        .count   (count)
    );

    // Reference queue: 256-entry ring with 8-bit indices (DEPTH must be <= 255).
    reg [WIDTH-1:0] q_mem [0:255];
    reg [7:0]       q_head   = 8'd0;
    reg [7:0]       q_tail   = 8'd0;
    reg [31:0]      q_cnt    = 32'd0;
    reg [31:0]      wptr_m   = 32'd0;   // mirrors the DUT write pointer
    reg [31:0]      rptr_m   = 32'd0;   // mirrors the DUT read pointer
    reg             checking = 1'b0;
    reg [9:0]       cov_q    = 10'd0;

    wire [31:0] count_ext = {{(32-CW){1'b0}}, count};
    wire        m_full    = (q_cnt == DEPTH);
    wire        m_empty   = (q_cnt == 32'd0);
    wire        m_wr      = wr_en && !m_full;
    wire        m_rd      = rd_en && !m_empty;

    assign cov = cov_q;

    // Model update and coverage, from pre-edge state.
    always @(posedge clk) begin
        if (!rst_n) begin
            if (checking && (q_cnt != 32'd0)) cov_q[9] <= 1'b1;
            q_head   <= 8'd0;
            q_tail   <= 8'd0;
            q_cnt    <= 32'd0;
            wptr_m   <= 32'd0;
            rptr_m   <= 32'd0;
            checking <= 1'b1;
        end else if (checking) begin
            if (m_wr) begin
                q_mem[q_tail] <= wr_data;
                q_tail <= q_tail + 8'd1;
                wptr_m <= (wptr_m == DEPTH - 1) ? 32'd0 : wptr_m + 32'd1;
            end
            if (m_rd) begin
                q_head <= q_head + 8'd1;
                rptr_m <= (rptr_m == DEPTH - 1) ? 32'd0 : rptr_m + 32'd1;
            end
            q_cnt <= q_cnt + {31'd0, m_wr} - {31'd0, m_rd};

            if (m_wr && !m_rd && (q_cnt == DEPTH - 1)) cov_q[0] <= 1'b1;
            if (wr_en && m_full)                        cov_q[1] <= 1'b1;
            if (m_rd && !m_wr && (q_cnt == 32'd1))      cov_q[2] <= 1'b1;
            if (rd_en && m_empty)                       cov_q[3] <= 1'b1;
            if (wr_en && rd_en && m_empty)              cov_q[4] <= 1'b1;
            if (wr_en && rd_en && m_full)               cov_q[5] <= 1'b1;
            if (wr_en && rd_en && !m_empty && !m_full)  cov_q[6] <= 1'b1;
            if (m_wr && (wptr_m == DEPTH - 1))          cov_q[7] <= 1'b1;
            if (m_rd && (rptr_m == DEPTH - 1))          cov_q[8] <= 1'b1;
        end
    end

    // Per-cycle checks, at the falling edge after outputs settle.
    initial begin
        passed = 32'd0;
        failed = 32'd0;
        forever begin
            @(negedge clk);
            if (checking) begin
                if (full !== m_full) begin
                    failed = failed + 32'd1;
                    $error("lane D%0d W%0d: full is %b, expected %b", DEPTH, WIDTH, full, m_full);
                end else begin
                    passed = passed + 32'd1;
                end

                if (empty !== m_empty) begin
                    failed = failed + 32'd1;
                    $error("lane D%0d W%0d: empty is %b, expected %b", DEPTH, WIDTH, empty, m_empty);
                end else begin
                    passed = passed + 32'd1;
                end

                if (count_ext !== q_cnt) begin
                    failed = failed + 32'd1;
                    $error("lane D%0d W%0d: count is %0d, expected %0d", DEPTH, WIDTH, count, q_cnt);
                end else begin
                    passed = passed + 32'd1;
                end

                if (full === 1'b1 && empty === 1'b1) begin
                    failed = failed + 32'd1;
                    $error("lane D%0d W%0d: full and empty both high", DEPTH, WIDTH);
                end else begin
                    passed = passed + 32'd1;
                end

                if (!m_empty) begin
                    if (rd_data !== q_mem[q_head]) begin
                        failed = failed + 32'd1;
                        $error("lane D%0d W%0d: rd_data is %h, expected %h", DEPTH, WIDTH, rd_data, q_mem[q_head]);
                    end else begin
                        passed = passed + 32'd1;
                    end
                end
            end
        end
    end

endmodule
=== END FILE ===
